TLM.f("Sancti/06-30",{"officium":"In Commemoratione Sancti Pauli Apostoli","rule":["Evangelium non appropriatum","ex C1;","Gloria","CredoDA","Prefatio=Apostolis","Sub unica concl"],"ruleInherited":["Psalmi Dominica","Antiphonas horas","Psalm5 Vespera=116","Psalm5 Vespera3=138"],"fallback":"Commune/C1","sections":{"Introitus":[{"k":"ref","la":"2 Tim 1:12"},{"k":"text","la":"Scio, cui crédidi, et certus sum, quia potens est depósitum meum servare in illum diem, justus judex."},{"k":"ref","la":"Ps 138:1-2"},{"k":"text","la":"Dómine, probásti me et cognovísti me: tu cognovísti sessiónem meam et resurrectiónem meam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Scio, cui crédidi, et certus sum, quia potens est depósitum meum servare in illum diem, justus judex."}],"Oratio":[{"k":"text","la":"Deus, qui multitúdinem géntium beáti Pauli Apóstoli prædicatióne docuísti: da nobis, quǽsumus; ut, cujus natalícia cólimus, ejus apud te patrocínia sentiámus."},{"k":"macro","name":"Per Dominum"},{"k":"sep"},{"k":"macro","name":"Oremus"},{"k":"rubric","la":"Pro S. Petro"},{"k":"text","la":"Deus, qui beáto Petro Apóstolo tuo, collátis clávibus regni Cœléstis, ligándi atque solvéndi pontifícium tradidísti: concéde; ut, intercessiónis ejus auxílio, a peccatórum nostrórum néxibus liberémur."},{"k":"macro","name":"Qui vivis"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Gálatas"},{"k":"ref","la":"Gal 1:11-20"},{"k":"text","la":"Fratres: Notum vobis facio Evangélium, quod evangelizátum est a me, quia non est secúndum hóminem: neque enim ego ab hómine accépi illud neque dídici, sed per revelatiónem Jesu Christi. Audístis enim conversatiónem meam aliquándo in Judaísmo: quóniam supra modum persequébar Ecclésiam Dei, et expugnábam illam, et proficiébam in Judaísmo supra multos coætáneos meos in génere meo, abundántius æmulátor exsístens paternárum mearum traditiónum. Cum autem plácuit ei, qui me segregávit ex útero matris meæ, et vocávit per grátiam suam, ut reveláret Fílium suum in me, ut evangelizárem illum in géntibus: contínuo non acquiévi carni et sánguini, neque veni Jerosólymam ad antecessóres meos Apóstolos: sed ábii in Arábiam: et íterum revérsus sum Damáscum: déinde post annos tres veni Jerosólymam vidére Petrum, et mansi apud eum diébus quíndecim: álium autem Apostolórum vidi néminem, nisi Jacóbum fratrem Dómini. Quæ autem scribo vobis, ecce coram Deo, quia non méntior."}],"Graduale":[{"k":"ref","la":"Gal 2:8-9"},{"k":"text","la":"Qui operátus est Petro in apostolátum, operátus est et mihi inter gentes: et cognovérunt grátiam Dei, quæ data est mihi."},{"k":"ref","la":"1 Cor 15:10"},{"k":"text","la":"Grátia Dei in me vácua non fuit: sed grátia ejus semper in me manet. Allelúja, allelúja."},{"k":"text","la":"Sancte Paule Apóstole, prædicátor veritátis et doctor géntium, intercéde pro nobis. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 106:8"},{"k":"text","la":"Confiteántur Dómino misericórdiæ ejus. et mirabília ejus fíliis hóminum. Allelúja."},{"k":"text","la":"Sancte Paule Apóstole, prædicátor veritátis et doctor géntium, intercéde pro nobis. Allelúja.","mark":"V"}],"Tractus":[{"k":"text","la":"Tu es vas electiónis, sancte Paule Apóstole: vere digne es glorificándus."},{"k":"text","la":"Prædicátor veritátis et doctor géntium in fide et veritáte.","mark":"V"},{"k":"text","la":"Per te omnes gentes cognovérunt grátiam Dei.","mark":"V"},{"k":"text","la":"Intercéde pro nobis ad Deum, qui te elégit.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 10:16-22"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Ecce, ego mitto vos sicut oves in médio lupórum. Estóte ergo prudéntes sicut serpentes, et símplices sicut colúmbæ. Cavéte autem ab homínibus. Tradent enim vos in concíliis, et in synagógis suis flagellábunt vos: et ad præsides et ad reges ducémini propter me in testimónium illis et géntibus. Cum autem tradent vos, nolíte cogitáre, quómodo aut quid loquámini: dábitur enim vobis in illa hora, quid loquámini. Non enim vos estis, qui loquímini, sed Spíritus Patris vestri, qui lóquitur in vobis. Tradet autem frater fratrem in mortem, et pater fílium: et insúrgent fílii in paréntes, et morte eos affícient: et éritis odio ómnibus propter nomen meum: qui autem perseveráverit usque in finem, hic salvus erit."}],"Offertorium":[{"k":"ref","la":"Ps 138:17"},{"k":"text","la":"Mihi autem nimis honoráti sunt amíci tui, Deus: nimis confortátus est principátus eórum."}],"Secreta":[{"k":"text","la":"Apóstoli tui Pauli précibus, Dómine, plebis tuæ dona sanctífica: ut, quæ tibi tuo grata sunt institúto, gratióra fiant patrocínio supplicántis."},{"k":"macro","name":"Per Dominum"},{"k":"sep"},{"k":"macro","name":"Oremus"},{"k":"rubric","la":"Pro S. Petro"},{"k":"text","la":"Ecclésiæ tuæ, quǽsumus, Dómine, preces et hóstias beáti Petri Apóstoli comméndet orátio: ut, quod pro illíus glória celebrámus, nobis prosit ad véniam."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 19:28-29"},{"k":"text","la":"Amen, dico vobis: quod vos, qui reliquístis ómnia et secúti estis me, céntuplum accipiétis, et vitam ætérnam possidébitis. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Percéptis, Dómine, sacraméntis: beáto Paulo Apóstolo tuo interveniénte, deprecámur; ut, quæ pro illíus celebráta sunt glória, nobis profíciant ad medélam."},{"k":"macro","name":"Per Dominum"},{"k":"sep"},{"k":"macro","name":"Oremus"},{"k":"rubric","la":"Pro S. Petro"},{"k":"text","la":"Lætíficet nos, Dómine, munus oblátum: ut, sicut in Apóstolo tuo Petro te mirábilem prædicámus; sic per illum tuæ sumamus indulgéntiæ largitátem."},{"k":"macro","name":"Per Dominum"}]},"hr":{"5dcf5fbe3d311635":{"t":"2 Tim 1, 12, Ps 138, 1-2\n(2 Tim 1, 12) Znam komu sam vjerovao i uvjeren sam da on može sačuvati zaklad moj za onaj dan. (Ps 138, 1-2) Gospodine, ti si me kušao i spoznao, tebi je poznat moj počinak i moje uskrsnuće.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(2 Tim 1, 12) Znam komu sam vjerovao i uvjeren sam da on može sačuvati zaklad moj za onaj dan.","kn":"(2. Tim. 1, 12). Znam, komu sam vjerovao i uvjeren sam, da je kao pravedni sudac kadar poklad moj sačuvati za onaj dan. (Ps. 138, 1, 2). Gospodine, Ti si me kušao i spoznao; Tebi je poznat moj počinak i moje ustajanje. Slava Ocu... Znam...","knRef":"Kniewald 1942, str. 488–489 (snimka 245) (OCR)"},"1ab201f48891cb83":{"t":"<i>Pomolimo se</i>.\nBože, koji si mnoge narode poučio propovijedanjem blaženog Pavla apostola, daj nam, molimo, da osjetimo zaštitu kod tebe onoga čiji rođendan slavimo.","kn":"Bože, koji si mnoge narode poučio propovijedanjem blaženoga Pavla apostola, podaj, molimo Te, da nas kod Tebe zagovara onaj, kojega rođeni dan slavimo, po G. n.","knRef":"Kniewald 1942, str. 618–619 (snimka 310) (OCR)"},"12b566b864ba22e4":{"t":"Bože, koji si blaženom Petru apostolu predao ključeve kraljevstva nebeskoga i time velikosvećeničku vlast vezanja i odrješivanja, daj da se po njegovu zagovoru izbavimo od veza naših grijeha.\n<i>Koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si blaženomu Petru, apostolu svome, dao ključeve kraljevstva nebeskoga i vrhovnu vlast vezati i razriješiti, podaj, da se po njegovu zagovoru izbavimo od naših grijeha.","knRef":"Kniewald 1942, str. 618–619 (snimka 310) (OCR)"},"bdac5376fd5192c3":{"t":"Gal 1, 11-20\nČitanje Poslanice bl. Pavla apostola Galaćanima. Braćo, objavljujem vam da evanđelje koje sam vam propovijedao nije ljudsko djelo, jer niti sam ga primio niti naučio od čovjeka, nego po objavi Isusa Krista. Ćuli ste, valjda, kako sam se nekada vladao u židovstvu, kako sam strašno progonio Božju Crkvu i pustošio je, a u židovstvu sam zbog svoje revne privrženosti očinskim predajama bio viđeniji nego toliki vršnjaci mojega naroda. Ali kada se svidjelo onome koji me još u krilu majke izabra, i po svojoj milosti me pozva da mi objavi svojega Sina da ga navješćujem nevjernicima, ja se nisam povjerio ljudima niti sam pošao u Jeruzalem k apostolima, starijima od sebe, nego sam pošao u Arabiju i ponovo se vratio u Damask. Istom sam nakon tri godine pošao u Jeruzalem da vidim Petra, kod kojega sam i ostao petnaest dana. Od apostola nisam vidio drugoga osim Gospodnjega brata Jakova. Bog mi je svjedok da ne lažem kada vam ovo pišem!","kn":"Čitanje poslanice bi. Pavla apostola Galaćanlma (1, 11-20): Braćo! Izjavljujem vam, da evanđelje, koje sam vam propovijedao, nije ljudsko djelo, jer niti sam ga primio niti naučio od čovjeka, nego po objavi Isusa Krista. Ćuli ste, kako sam nekada vladao u židovstvu, kako sam pre ko mjere progonio Crkvu Božju ipustošio je. I napredovao sam u židovstvu više nego mnogt moji vršnjaci iz mojega naroda, i bio sam vrlo revan za predaje svojih otaca. A kad se svidjelo onomu, koji me je odabrao još iz majčina krila, i po svojoj me milosti pozvao, da u meni objavi svojega Sina, da' ga navješćujem među neznabos- cima, ni jesam se ja povjerio ljudima, niti sam pošao u Jeruzalem k apostolima starijim od sebe, nego sam otišao u Arabiju i opet se vratio u Damask. Zatim sam poslije tri godine došao u Jeruzalem da vidim Petra, kod kojega sam i ostao petnaest dana. Nijednoga drugog od apostola nijesam vidio osim Jakova, Gospodnjega brata,* A da ne lažem ovo, što vam pišem: Bog mi je svjedok I","knRef":"Kniewald 1942, str. 618–619 (snimka 310) (OCR)"},"8b2cd427374a9b54":{"t":"Gal 2, 8 i 9, 1 Kor 15, 10\n(Gal 2, 8 i 9) Onaj koji je pomagao Petru u apostolatu pomagao je i meni među narodima, tako da su upoznali milost Božju koja mi je dana. (1 Kor 15, 10) Milost Božja nije u meni bila neplodna, nego njegova milost trajno prebiva u meni.\n\n<i>Aleluja</i>, <i>aleluja</i>.\nSveti Pavle, apostole, ti si propovjednik istine i učitelj naroda. Zagovaraj nas! <i>Aleluja</i>.","kn":"(Gal. 2, 8). Onaj, koji pomože Petru u apostolstvu, pomaže i meni među poganima, i upoznaše milost Božju, koja je meni dana. (I. Kor. 15, 10). Milost Božja nije bila bez ploda u meni, nego milost njegova uvijek je sa mnom.\n\nAleluja, aleluja. Sveti Pavle apostole, propovjedniče istine, i učitelju naroda, zagovaraj nas!","knRef":"Kniewald 1942, str. 620–621 (snimka 311) (OCR)"},"b7c6408ffcda5d52":{"t":"Mt 10, 16-22\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme reče Isus svojim učenicima: Evo, ja vas šaljem kao ovce među vukove. Zato budite mudri kao zmije, a bezazleni kao golubovi. Čuvajte se ljudi, jer će vas predavati sudovima, bičevat će vas po svojim zbornicama, radi mene vodit će vas pred upravitelje i vladare, da svjedočite njima i nevjernicima. Kada budete u njihovim rukama, ne mučite se smišljajući kako ili što ćete govoriti, jer će vam se onoga časa objaviti što ćete govoriti. Nećete govoriti vi, nego će Duh vašega Oca govoriti iz vas. Predavat će na smrt brat brata, otac sina, dizat će se djeca na roditelje tražeći njihovu smrt. Svi će vas mrziti radi mene, ali tko ustraje do kraja, spasit će se.","kn":"t Slijedi sveto evanđelje po Mateju (10, 16-22). U ono vrijeme reče Isus svojim učenicima; Evo, šaljem vas kao ovce među vukove. Zato budite mudri kao zmije, a bezazleni kao golubovi. A čuvajte se ljudi! Oni će vas predavati sudovimai i bičevat će vas u svojim zbornicama, i vodit će vas pred upravitelje i kraljeve radi mene, da svjedočite njima i neznabošcima. Kada vas predaju, ne budite u skrbi, kako ili što ćete govoriti, jer će vam se onoga časa dati, što ćete govoriti. Ne ćete vi govoriti, nego Duh vašega Oca govorit će u vama. Predat će na smrt brat brata i otac sina, na smrt. I svi će vas mrziti radi mene, a spasit će se onaj, koji ustraje do kraja.","knRef":"Kniewald 1942, str. 620–621 (snimka 311) (OCR)"},"8bade162dbdb175e":{"t":"Ps 138, 17\nNada sve častim tvoje prijatelje, Bože, jer je velika uloga vlasti njihove.","kn":"(Ps. 138, 17). Veoma častim prijatelje Tvoje, Bože, silno se utvrdi kneževstvo njihovo!","knRef":"Kniewald 1942, str. 742–743 (snimka 372) (OCR)"},"f43c659e380d72b6":{"t":"Posveti, Gospodine, po molitvama svoga apostola Pavla darove svoga naroda, koji su ti mili jer si ih ustanovio, pa neka ti budu miliji po zagovoru našega zaštitnika.","kn":"Posveti, Gospodine, molitvama apostola svoga Pavla dare puka svoga, da ono, što Ti je ugodno, jer si to sam ustanovio, bude Tebi još ugodnije poradi njegova zagovora, po G. n. I. K.","knRef":"Kniewald 1942, str. 620–621 (snimka 311) (OCR)"},"0fe93625122c551c":{"t":"Molitva blaženoga Petra apostola neka preporuči, molimo, Gospodine, molitve i darove tvoje Crkve, da nama koristi za oproštenje što njemu na čast svetkujemo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, Gospodine, neka prošnje i žrtve Tvoje Crkve preporuči molitva blaženoga Petra Apostola, da nam uskoristi za oproštenje, što svetkujemo na njegovu slavu, po G. n.","knRef":"Kniewald 1942, str. 480–481 (snimka 241) (OCR)"},"fdbfd5e8960de5c2":{"t":"Uistinu je dostojno, i pravedno, pravo i spasonosno tebe, Gospodine, vječni Pastiru, smjerno moliti da stado svoje ne ostaviš, nego da ga po svojim blaženim apostolima neprestano štitiš i čuvaš, da njime ravnaju isti poglavari, koje si mu postavio na čelo kao pastire i namjesnike svoga djela. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno. Tebe, Gospodine, vječni Pastiru, smjerno moliti, da ne ostaviš svoga stada, nego’ da ga po blaženim svojim apostolima sveudiljnom zaštitom čuvaš, te Tvojim stadom upravljaju isti vođe, koje si Ti odredio da ga vode kao pastiri i namjesnici Tvoga djelovanja. I toga radi pjevamo pjesmu slave Tvoje s anđelima i s arkanđelima, s prijestolima i s gospodstvima i sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 618–619 (snimka 310) (OCR)"},"d76f89b9ab1556d0":{"t":"Mt 19, 28 i 29\nZaista vam kažem da ćete vi koji ste ostavili sve i pošli za mnom primiti stostruko i baštiniti život vječni.","kn":"(Mt. 19, 28, 29). Zaista vam kažem, da čete vi, koji ste sve ostavili 1 koji ste pošli za mnom, primiti stoput onoliko i baštinit ćete život vječni.","knRef":"Kniewald 1942, str. 620–621 (snimka 311) (OCR)"},"ab5f6b105ea8470b":{"t":"<i>Pomolimo se</i>.\nPošto smo primili otajstva, molimo. Gospodine, po zagovoru blaženog Pavla apostola tvoga da nam koristi kao lijek što smo slavili njemu na čast.","kn":"Primivši, Gospodine, svetotajstv^, molimo Te zagovorom blaženoga apostola Pavla, da nama bude za lijek, što smo slavili njemu na slavu, po G. n. I. K.","knRef":"Kniewald 1942, str. 620–621 (snimka 311) (OCR)"},"4dbe0d4385fb1374":{"t":"Neka nas, Gospodine, razveseli prikazani dar da po tvome apostolu Petru tako primimo tvoje obilno oproštenje kao što u njemu slavimo tvoja čudesa.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Neka nas obraduje. Gospodine, žrtvovani dar, te kao što veličamo čudesa Tvoja u Tvom apostolu Petru, takonam po njemu udijeli obilje Tvog ciproštenja, -po G. n.","knRef":"Kniewald 1942, str. 480–481 (snimka 241) (OCR)"}}});
